/* ---------- carga inicial ---------- */
var aoCarregarAT = [];
function quandoAT(fn) { if (AT) fn(); else aoCarregarAT.push(fn); }
function carregar() {
call('bootstrap').then(function (b) {
BOOT = b;
var email = b.usuario.email || '';
$("#chip-nome").textContent = quemSou(); $("#chip-av").textContent = quemSou().charAt(0);
